const AlumnosPage = ({ asignaciones }) => {
  const { grado, division, materiaId } = useParams();
  const [alumnos, setAlumnos] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingAlumno, setEditingAlumno] = useState(null);
  const [formData, setFormData] = useState({
    nombre: '',
    apellido: '',
    nivel: 'LE',
    observaciones: '',
  });

  // Encontrar la asignación actual
  const asignacionActual = asignaciones.find(
    a => a.grado === grado && a.division === division && a.materia_id === parseInt(materiaId)
  );

  // Cargar alumnos del localStorage (simulado, en producción sería API)
  useEffect(() => {
    const key = `alumnos_${grado}_${division}`;
    const stored = localStorage.getItem(key);
    if (stored) {
      setAlumnos(JSON.parse(stored));
    }
  }, [grado, division]);

  // Guardar alumnos en localStorage
  const saveAlumnos = (newAlumnos) => {
    const key = `alumnos_${grado}_${division}`;
    localStorage.setItem(key, JSON.stringify(newAlumnos));
    setAlumnos(newAlumnos);
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (editingAlumno) {
      // Actualizar alumno existente
      const updated = alumnos.map(a => 
        a.id === editingAlumno.id 
          ? { ...a, ...formData, niveles: { ...a.niveles, [materiaId]: formData.nivel } }
          : a
      );
      saveAlumnos(updated);
    } else {
      // Crear nuevo alumno
      const nuevoAlumno = {
        id: Date.now(),
        ...formData,
        niveles: { [materiaId]: formData.nivel },
      };
      saveAlumnos([...alumnos, nuevoAlumno]);
    }

    resetForm();
  };

  const handleEdit = (alumno) => {
    setEditingAlumno(alumno);
    setFormData({
      nombre: alumno.nombre,
      apellido: alumno.apellido,
      nivel: alumno.niveles?.[materiaId] || 'LE',
      observaciones: alumno.observaciones || '',
    });
    setShowForm(true);
  };

  const handleDelete = (id) => {
    if (window.confirm('¿Estás seguro de eliminar este alumno?')) {
      saveAlumnos(alumnos.filter(a => a.id !== id));
    }
  };

  const handleNivelChange = (alumnoId, nuevoNivel) => {
    const updated = alumnos.map(a => 
      a.id === alumnoId 
        ? { ...a, niveles: { ...a.niveles, [materiaId]: nuevoNivel } }
        : a
    );
    saveAlumnos(updated);
  };

  const resetForm = () => {
    setFormData({ nombre: '', apellido: '', nivel: 'LE', observaciones: '' });
    setEditingAlumno(null);
    setShowForm(false);
  };

  // Contar alumnos por nivel
  const contarPorNivel = (nivel) => 
    alumnos.filter(a => (a.niveles?.[materiaId] || 'LE') === nivel).length;

  if (!asignacionActual) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-500">Asignación no encontrada</p>
      </div>
    );
  }

  return (
    <div>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">
            Alumnos de {grado}° {division}
          </h1>
          <p className="text-gray-600 mt-1">{asignacionActual.materia_nombre}</p>
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors flex items-center"
        >
          <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Agregar Alumno
        </button>
      </div>

      {/* Resumen por niveles */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="bg-red-50 border border-red-200 rounded-xl p-4 text-center">
          <p className="text-3xl font-bold text-red-700">{contarPorNivel('NEET')}</p>
          <p className="text-sm text-red-600">NEET - Rezago Significativo</p>
        </div>
        <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4 text-center">
          <p className="text-3xl font-bold text-yellow-700">{contarPorNivel('LP')}</p>
          <p className="text-sm text-yellow-600">LP - Logros en Proceso</p>
        </div>
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 text-center">
          <p className="text-3xl font-bold text-green-700">{contarPorNivel('LE')}</p>
          <p className="text-sm text-green-600">LE - Logros Esperados</p>
        </div>
      </div>

      {/* Modal de formulario */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md mx-4">
            <h2 className="text-xl font-semibold mb-4">
              {editingAlumno ? 'Editar Alumno' : 'Nuevo Alumno'}
            </h2>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nombre</label>
                  <input
                    type="text"
                    value={formData.nombre}
                    onChange={(e) => setFormData({ ...formData, nombre: e.target.value })}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Apellido</label>
                  <input
                    type="text"
                    value={formData.apellido}
                    onChange={(e) => setFormData({ ...formData, apellido: e.target.value })}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Nivel en {asignacionActual.materia_nombre}
                </label>
                <NivelSelector
                  value={formData.nivel}
                  onChange={(nivel) => setFormData({ ...formData, nivel })}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Observaciones (opcional)
                </label>
                <textarea
                  value={formData.observaciones}
                  onChange={(e) => setFormData({ ...formData, observaciones: e.target.value })}
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  placeholder="Notas sobre el alumno que ayuden a la IA..."
                />
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={resetForm}
                  className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  {editingAlumno ? 'Guardar Cambios' : 'Agregar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Lista de alumnos */}
      {alumnos.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <svg className="w-16 h-16 text-gray-300 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
          </svg>
          <h3 className="text-lg font-medium text-gray-900 mb-2">Sin alumnos cargados</h3>
          <p className="text-gray-500 mb-4">Agregá los alumnos de este curso para personalizar las planificaciones</p>
          <button
            onClick={() => setShowForm(true)}
            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
          >
            Agregar Primer Alumno
          </button>
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Alumno
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Nivel
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Observaciones
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {alumnos.map((alumno) => (
                <tr key={alumno.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="font-medium text-gray-900">
                      {alumno.apellido}, {alumno.nombre}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <select
                      value={alumno.niveles?.[materiaId] || 'LE'}
                      onChange={(e) => handleNivelChange(alumno.id, e.target.value)}
                      className="border-0 bg-transparent focus:ring-0 cursor-pointer"
                    >
                      <option value="NEET">NEET</option>
                      <option value="LP">LP</option>
                      <option value="LE">LE</option>
                    </select>
                    <NivelBadge nivel={alumno.niveles?.[materiaId] || 'LE'} size="sm" />
                  </td>
                  <td className="px-6 py-4">
                    <p className="text-sm text-gray-500 truncate max-w-xs">
                      {alumno.observaciones || '-'}
                    </p>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <button
                      onClick={() => handleEdit(alumno)}
                      className="text-indigo-600 hover:text-indigo-800 mr-3"
                    >
                      Editar
                    </button>
                    <button
                      onClick={() => handleDelete(alumno.id)}
                      className="text-red-600 hover:text-red-800"
                    >
                      Eliminar
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default AlumnosPage;
